use super::misc::dominates_or_equal;
use rand::Rng;
use rand::rngs::StdRng;

pub(super) struct HypervolumeSamples {
    pub(super) points: Vec<Vec<f64>>,
    pub(super) front_dominated: Vec<bool>,
    pub(super) volume: f64,
}

impl HypervolumeSamples {
    pub(super) fn new(
        front: &[Vec<f64>],
        lower: &[f64],
        reference: &[f64],
        draws: usize,
        rng: &mut StdRng,
    ) -> Self {
        if lower.len() != reference.len() || lower.iter().zip(reference).any(|(lo, hi)| lo >= hi) {
            return Self {
                points: Vec::new(),
                front_dominated: Vec::new(),
                volume: 0.0,
            };
        }

        let volume = lower
            .iter()
            .zip(reference.iter())
            .map(|(lo, hi)| hi - lo)
            .product::<f64>();
        let mut points = Vec::with_capacity(draws.max(1));
        let mut front_dominated = Vec::with_capacity(draws.max(1));
        for _ in 0..draws.max(1) {
            let point = lower
                .iter()
                .zip(reference.iter())
                .map(|(lo, hi)| lo + rng.random::<f64>() * (hi - lo))
                .collect::<Vec<_>>();
            front_dominated.push(front.iter().any(|p| dominates_or_equal(p, &point)));
            points.push(point);
        }

        Self {
            points,
            front_dominated,
            volume,
        }
    }
}
